// Cada item é um agendamento que precisa de lembrete
// Estrutura esperada da RPC get_appointments_needing_reminder:
// {
//   id, client_id, customer_name, customer_email, customer_phone,
//   whatsapp_notify_phone, service_name, start_at, end_at,
//   email_notify_enabled, email_notify_on_reminder, email_reminder_hours,
//   whatsapp_notify_enabled, whatsapp_notify_on_reminder, whatsapp_reminder_hours,
//   email_reminder_sent_at, reminder_sent_at  -- null = ainda não enviado
// }
const appt = $input.first().json;

// Formata data/hora
const fmtDate = (iso) => {
  try {
    return new Date(iso).toLocaleDateString('pt-BR', { weekday: 'long', day: '2-digit', month: 'long' });
  } catch { return iso; }
};
const fmtTime = (iso) => {
  try {
    return new Date(iso).toLocaleTimeString('pt-BR', { hour: '2-digit', minute: '2-digit', timeZone: 'America/Sao_Paulo' });
  } catch { return iso; }
};

// Normaliza telefone para WhatsApp
const normalizePhone = (phone) => {
  if (!phone) return null;
  let p = phone.replace(/\D/g, '');
  if (!p.startsWith('55')) p = '55' + p;
  return '+' + p;
};

const sendEmail    = (appt.email_notify_enabled    && appt.email_notify_on_reminder    && !appt.email_reminder_sent_at);
const sendWhatsapp = (appt.whatsapp_notify_enabled && appt.whatsapp_notify_on_reminder && !appt.reminder_sent_at);

return [{
  json: {
    appointment_id: appt.id,
    client_id:      appt.client_id,
    customer_name:  appt.customer_name,
    customer_email: appt.customer_email,
    customer_phone: normalizePhone(appt.whatsapp_notify_phone ?? appt.customer_phone),
    service_name:   appt.service_name,
    start_at:       appt.start_at,
    end_at:         appt.end_at,
    data:           fmtDate(appt.start_at),
    hora:           fmtTime(appt.start_at),
    send_email:     sendEmail,
    send_whatsapp:  sendWhatsapp,
    skip:           !sendEmail && !sendWhatsapp,
  }
}];

