const cfg  = ($input.first().json[0] ?? $input.first().json) || {};
const appt = $('Preparar Lembrete').first().json;

// Substitui variáveis de template
const vars = { nome: appt.customer_name, servico: appt.service_name, data: appt.data, hora: appt.hora };
const applyVars = (tpl) => tpl.replace(/\{(\w+)\}/g, (_, k) => vars[k] ?? `{${k}}`);

const rawMsg  = cfg.whatsapp_msg_reminder;
const message = rawMsg?.trim()
  ? applyVars(rawMsg)
  : `⏰ Olá, ${appt.customer_name}! Lembrete: você tem *${appt.service_name}* em ${appt.data} às ${appt.hora}. Qualquer dúvida, entre em contato!`;

return [{
  json: {
    connection_id: cfg.whatsapp_connection_id ?? null,
    phone:         appt.customer_phone,
    message,
    appointment_id: appt.appointment_id,
  }
}];

